import {sources} from './grid-queues-scenes.js';
import {ercotSnapshot,ercotGroups,dominionSnapshot,projectOptions,securityFaceAmount,stagedLoad} from './grid-queues-model.js';
const credit=(label,url)=>`<p class="q-credit"><a href="${url}" target="_blank" rel="noreferrer">${label}</a></p>`;
const arrow='<span class="q-arrow" aria-hidden="true">→</span>';
const rack=(cls='')=>`<span class="q-rack ${cls}" aria-hidden="true"><i></i><i></i><i></i><i></i></span>`;
const asset=file=>`../assets/references/${file}`;
const figure=(file,alt,credits)=>`<figure class="q-source-figure"><a class="full-size-figure" href="${asset(file)}" target="_blank" rel="noopener" aria-label="Open full-size source figure"><img src="${asset(file)}" alt="${alt}"></a><figcaption>${credits}</figcaption></figure>`;
function unpowered(){
 return `<div class="q-stack"><div class="q-unpowered"><section class="q-network"><div class="q-mesh" aria-hidden="true"><i></i><i></i><i></i><i></i></div><h2>The grid</h2><p>Electricity</p></section><span class="q-gap"><i aria-hidden="true"></i><b>No connection yet</b><i aria-hidden="true"></i></span><section class="q-end"><span class="q-kicker">Delivered</span><h2>GPU racks</h2>${rack('dark')}<p>Not plugged in</p></section></div><blockquote class="q-quote"><p>“a bunch of chips sitting in inventory that I can’t plug in”</p><cite>Satya Nadella, Microsoft CEO · October 2025</cite></blockquote>${credit('BG2 podcast · October 31, 2025',sources.nadella)}</div>`;
}
function pipeline(){
 const m=ercotSnapshot,groups=ercotGroups(m),approved=groups.at(-1);
 const label=groups.map(g=>`${g.gw.toFixed(1)} GW ${g.label}`).join(', ');
 return `<div class="q-stack"><p class="q-dateline">All ERCOT large-load requests since 2022, by status · as of ${m.date} · requested load by ${m.horizon}</p><div class="q-mix" role="img" aria-label="${m.totalGW} GW of requests: ${label}, of which ${m.observedGW} GW is observed operating">${groups.map(g=>`<span class="${g.key}" style="flex:${g.gw}">${g===approved?`<i style="width:${m.observedGW/g.gw*100}%"></i>`:''}</span>`).join('')}</div><div class="q-mix-legend">${groups.map(g=>`<span class="${g.key}"><b>${g.gw.toFixed(1)} GW</b>${g.label}</span>`).join('')}</div><div class="q-observed"><strong>${m.observedGW} GW</strong><span>Observed operating · each site’s peak, added up</span></div>${credit('ERCOT Senate presentation · July 29, 2026 · six status rows grouped into three',sources.ercot)}</div>`;
}
function options(){
 const m=projectOptions();
 return `<div class="q-options"><div class="q-project"><span>One planned deployment</span><strong>${m.plannedMW/1000} GW</strong></div><div class="q-site-branches" aria-hidden="true"></div><div class="q-sites">${m.sites.map(id=>`<section><h2>Site ${id}</h2>${rack()}<strong>1 GW request</strong></section>`).join('')}</div><p class="q-option-total"><strong>${m.requestedMW/1000} GW</strong> of requests <span>·</span> <strong>${m.plannedMW/1000} GW</strong> planned campus</p></div>`;
}
function commitments(){return `<div class="q-stack"><div class="q-two q-money"><section class="before"><span class="q-kicker">Before SB 6 · 2025</span><strong>No ERCOT-wide amount</strong><p>Each utility set its own study charges and security</p></section><section><span class="q-kicker">From October 8, 2026</span><strong>$100,000 study fee<br>$50,000 / MW security</strong><p>Due before ERCOT studies a new request of 75 MW or more</p></section></div><div class="q-security-example"><span>1 GW request</span>${arrow}<strong>$${securityFaceAmount(1000)/1e6} million</strong><span>security face amount</span></div>${credit('SB 6 signed June 20, 2025 · Texas rule adopted September 18 · effective October 8, 2026',sources.security)}</div>`;}
function dominionInPjm(){
 return `<div class="q-map-split"><figure class="q-map"><a class="full-size-figure" href="${asset('grid-queues-pjm-zones.png')}" target="_blank" rel="noopener" aria-label="Open full-size PJM zone map"><img src="${asset('grid-queues-pjm-zones.png')}" alt="PJM’s transmission-zone map. PJM spans from northern Illinois to New Jersey and North Carolina and is divided into utility zones such as ComEd, AEP, PPL and PSEG. The Dominion zone covers most of Virginia and part of North Carolina."></a><figcaption>${credit('PJM · Transmission Zones map, May 2023 · cropped to the map',sources.pjmZones)}</figcaption></figure><div class="q-roles"><section><span class="q-kicker">Grid operator</span><h2>PJM</h2><p>Runs the grid and the power market across 13 states and D.C. Owns no wires.</p></section><section class="dominion"><span class="q-kicker">Utility</span><h2>Dominion Energy Virginia</h2><p>The main utility in its zone. Data centers sign with the utility, not with PJM.</p></section><p class="q-analogy">In Texas: ERCOT, and a wires utility such as Oncor.</p></div></div>`;
}
function dominionContracts(){
 const m=dominionSnapshot,stages=[['engineering',m.engineeringGW,'Engineering study','Paid for by the customer. No obligation to build.'],['construction',m.constructionGW,'Construction authorized','The customer repays spent costs if it leaves.'],['service',m.serviceGW,'Service agreement','The customer pays whether or not it takes service.']];
 return `<div class="q-map-split q-contract-split"><figure class="q-map"><a class="full-size-figure" href="${asset('grid-queues-dominion-contracts.png')}" target="_blank" rel="noopener" aria-label="Open Dominion’s full slide"><img src="${asset('grid-queues-dominion-contracts-bars.png')}" alt="Dominion Energy Virginia data-center contracted capacity by stage, as stacked bars: about 16.5 GW in July 2023, 48.5 GW in December 2025, 51.0 GW in March 2026 and ${m.totalGW} GW in ${m.contractDate}. The ${m.contractDate} bar is ${m.engineeringGW} GW of substation engineering letters of authorization (SELOA), ${m.constructionGW} GW of construction letters of authorization (CLOA) and ${m.serviceGW.toFixed(1)} GW of electric service agreements (ESA)."></a><figcaption>${credit('Dominion Energy · Q2 2026 earnings slides, July 31, 2026 · cropped to the chart',sources.dominionContracts)}</figcaption></figure><div class="q-roles q-stages-key"><p class="q-kicker">Contracts · ${m.contractDate}</p>${stages.map(([key,gw,name,meaning])=>`<section class="${key}"><h2><b>${gw.toFixed(1)} GW</b> ${name}</h2><p>${meaning}</p></section>`).join('')}<div class="q-observed"><strong>≈ ${m.coincidentPeakGW} GW</strong><span>drawn by Dominion’s data centers at the ${m.peakYear} peak</span></div>${credit('Peak · Dominion letter to PJM, January 6, 2026',sources.dominion)}</div></div>`;
}
export function gridQueuesVisual(id){
 switch(id){
 case 'queue-purpose':return `<div class="q-logos"><div class="q-logo-plate"><img src="${asset('grid-queues-ercot-logo.svg')}" alt="ERCOT"></div><div class="q-logo-plate"><img src="${asset('grid-queues-pjm-logo.svg')}" alt="PJM"></div></div>`;
 case 'chips-need-power':return unpowered();
 case 'ercot-pipeline':return pipeline();
 case 'site-options':return options();
 case 'ercot-analyst':return figure('grid-queues-sa-requests.png','SemiAnalysis compares 410 GW total ERCOT requests, including 357 GW data centers in April 2026, with its 45.4 GW tracked data-center buildout through fourth quarter 2030. Phantom and duplicative classification is the publisher’s estimate.',credit('SemiAnalysis · June 18, 2026 · analyst model comparison',sources.saRequests));
 case 'commitment-costs':return commitments();
 case 'dominion-in-pjm':return dominionInPjm();
 case 'dominion-contracts':return dominionContracts();
 case 'forecast-filter':return figure('grid-queues-sa-forecast.png','Historical ERCOT 2025 system forecast: the 2030 submitted load is 208 GW and the adjusted forecast is 138 GW. This is the whole-system forecast, not a data-center-only queue.',credit('ERCOT 2025 forecast · reproduced by SemiAnalysis, March 3, 2026',sources.saForecast));
 case 'staged-connection':return `<div class="q-stack"><div class="q-stages">${[0,1,2].map(n=>`<section><h2>${['No generators ready','One generator ready','Both generators ready'][n]}</h2><div class="q-grid-limit">Grid limit: 100 MW</div><div class="q-generation" aria-label="${n} generators available">${[0,1].map(i=>`<span class="${i<n?'on':'off'}" aria-hidden="true">∿</span>`).join('')}</div><small>Local capacity: ${(n*500).toLocaleString('en-US')} MW</small><strong class="q-stage-output">${stagedLoad(n).toLocaleString('en-US')} MW</strong><small>${n===2?'Maximum load · the whole campus':'Maximum load'}</small></section>`).join('')}</div>${credit('Adapted from ERCOT’s May 2026 workshop illustration via SemiAnalysis',sources.saStaged)}</div>`;
 case 'btm-gap':return figure('grid-queues-sa-btm-gap.png','SemiAnalysis forecast of US data-center capacity added each year by power source. Totals rise from 21 GW in 2026 to 39, 54, 66 and 84 GW in 2030. Available grid capacity supplies 16.9 GW in 2026 and 14.6 GW in 2027, then nothing. The 2026 bar also has two small unlabelled segments of roughly 2 GW each: behind-the-meter at the bottom and new grid supply on top. New grid supply grows from 9.5 GW in 2027 to 18.3 GW in 2030. The remaining gap, labelled behind-the-meter, is 14.8 GW in 2027, 42.6 GW in 2028, 52.4 GW in 2029 and 65.7 GW in 2030.',credit('SemiAnalysis Energy Model · June 25, 2026 · analyst forecast of annual additions',sources.saStaged));
 default:throw new Error(`Unknown grid queue scene: ${id}`);
 }
}
